  for (const sel of ['#ds-linha-estado', '#ds-versos', '#ds-movimentos', '.ds-empty--hero', '.ds-anel[data-pct="100"]', '.ds-avatar']) assert.ok(await page.locator(sel).count() >= 1, sel);
