  const { page } = M; let e;
  for (let i = 0; i < 20; i++) { const o = await M.oid('Island'); if (o) await M.act({ t: 'play_land', p: 0, oid: o }); e = await M.est();
    if (e.campo.filter(n => n === 'Island').length >= 5 && e.mao.includes('Stream of Thought')) break; await M.proximo(); }
