  assert.match(await page.innerText('#pn-k-forca-medida'), /shark · motor v112 · 40 de 40 partidas · 0 ilegal/); assert.equal(await page.getAttribute('#pn-k-forca-medida .pn-farol', 'data-farol'), 'verde');
